32	/**
33	 * Security interceptor invoking {@link GrpcSecurityMechanism} implementations
34	 */
35	@GlobalInterceptor
36	@Singleton
37	public final class GrpcSecurityInterceptor implements ServerInterceptor, Prioritized {
38	
39	    private static final Logger log = Logger.getLogger(GrpcSecurityInterceptor.class);
40	
41	    private final IdentityProviderManager identityProviderManager;
42	    private final CurrentIdentityAssociation identityAssociation;
43	
44	    private final AuthExceptionHandlerProvider exceptionHandlerProvider;
45	    private final List<GrpcSecurityMechanism> securityMechanisms;
46	
47	    private final Map<String, List<String>> serviceToBlockingMethods = new HashMap<>();
48	    private boolean hasBlockingMethods = false;
49	
50	    @Inject
51	    public GrpcSecurityInterceptor(
52	            CurrentIdentityAssociation identityAssociation,
53	            IdentityProviderManager identityProviderManager,
54	            Instance<GrpcSecurityMechanism> securityMechanisms,
55	            Instance<AuthExceptionHandlerProvider> exceptionHandlers) {
56	        this.identityAssociation = identityAssociation;
57	        this.identityProviderManager = identityProviderManager;
58	
59	        AuthExceptionHandlerProvider maxPrioHandlerProvider = null;
60	
61	        for (AuthExceptionHandlerProvider handler : exceptionHandlers) {
62	            if (maxPrioHandlerProvider == null || maxPrioHandlerProvider.getPriority() < handler.getPriority()) {
63	                maxPrioHandlerProvider = handler;
64	            }
65	        }
66	        this.exceptionHandlerProvider = maxPrioHandlerProvider;
67	
68	        List<GrpcSecurityMechanism> mechanisms = new ArrayList<>();
69	        for (GrpcSecurityMechanism securityMechanism : securityMechanisms) {
70	            mechanisms.add(securityMechanism);
71	        }
72	        mechanisms.sort(Comparator.comparing(GrpcSecurityMechanism::getPriority));
73	        this.securityMechanisms = mechanisms;
74	    }
75	
76	    @Override
77	    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(ServerCall<ReqT, RespT> serverCall,
78	            Metadata metadata, ServerCallHandler<ReqT, RespT> serverCallHandler) {
79	        Exception error = null;
80	        for (GrpcSecurityMechanism securityMechanism : securityMechanisms) {
81	            if (securityMechanism.handles(metadata)) {
82	                try {
83	                    AuthenticationRequest authenticationRequest = securityMechanism.createAuthenticationRequest(metadata);
84	                    Context context = Vertx.currentContext();
85	                    boolean onEventLoopThread = Context.isOnEventLoopThread();
86	
87	                    final boolean isBlockingMethod;
88	                    if (hasBlockingMethods) {
89	                        var methods = serviceToBlockingMethods.get(serverCall.getMethodDescriptor().getServiceName());
90	                        if (methods != null) {
91	                            isBlockingMethod = methods.contains(serverCall.getMethodDescriptor().getFullMethodName());
92	                        } else {
93	                            isBlockingMethod = false;
94	                        }
95	                    } else {
96	                        isBlockingMethod = false;
97	                    }
98	
99	                    if (authenticationRequest != null) {
100	                        Uni<SecurityIdentity> auth = identityProviderManager
101	                                .authenticate(authenticationRequest)
102	                                .emitOn(new Executor() {
103	                                    @Override
104	                                    public void execute(Runnable command) {
105	                                        if (onEventLoopThread && !isBlockingMethod) {
106	                                            context.runOnContext(new Handler<>() {
107	                                                @Override
108	                                                public void handle(Void event) {
109	                                                    command.run();
110	                                                }
111	                                            });
112	                                        } else {
113	                                            command.run();
114	                                        }
115	                                    }
116	                                });
117	                        identityAssociation.setIdentity(auth);
118	                        error = null;
119	                        break;
120	                    }
121	                } catch (Exception e) {
122	                    error = e;
123	                    log.warn("Failed to prepare AuthenticationRequest for a gRPC call", e);
124	                }
125	            }
126	        }
127	        if (error != null) { // if parsing for all security mechanisms failed, let's propagate the last exception
128	            identityAssociation.setIdentity(Uni.createFrom()
129	                    .failure(new AuthenticationFailedException("Failed to parse authentication data", error)));
130	        }
131	        ServerCall.Listener<ReqT> listener = serverCallHandler.startCall(serverCall, metadata);
132	        return exceptionHandlerProvider.createHandler(listener, serverCall, metadata);
133	    }
134	
135	    @Override
136	    public int getPriority() {
137	        return Integer.MAX_VALUE - 100;
138	    }
139	
140	    void init(Map<String, List<String>> serviceToBlockingMethods) {
141	        this.serviceToBlockingMethods.putAll(serviceToBlockingMethods);
142	        this.hasBlockingMethods = true;
143	    }
144	}
