20	@Recorder
21	public class GrpcSecurityRecorder {
22	
23	    public void initGrpcSecurityInterceptor(Map<String, List<String>> serviceClassToBlockingMethod,
24	            BeanContainer container) {
25	
26	        // service to full method names
27	        var svcToMethods = new HashMap<String, List<String>>();
28	        var services = container.beanInstance(GrpcContainer.class).getServices();
29	        for (BindableService service : services) {
30	            var className = getImplementationClassName(service);
31	            var blockingMethods = serviceClassToBlockingMethod.get(className);
32	            if (blockingMethods != null && !blockingMethods.isEmpty()) {
33	                var svcName = service.bindService().getServiceDescriptor().getName();
34	                var methods = new ArrayList<String>();
35	                for (String blockingMethod : blockingMethods) {
36	                    for (ServerMethodDefinition<?, ?> method : service.bindService().getMethods()) {
37	                        if (blockingMethod.equals(method.getMethodDescriptor().getBareMethodName())) {
38	                            methods.add(method.getMethodDescriptor().getFullMethodName());
39	                            break;
40	                        }
41	                    }
42	                }
43	                svcToMethods.put(svcName, methods);
44	            }
45	        }
46	
47	        container.beanInstance(GrpcSecurityInterceptor.class).init(svcToMethods);
48	    }
49	
50	    public void validateSecurityEventsDisabled(String observedSecurityEvent) {
51	        boolean securityEventsEnabled = ConfigProvider
52	                .getConfig()
53	                .getOptionalValue("quarkus.security.events.enabled", boolean.class)
54	                .orElse(Boolean.TRUE);
55	        if (securityEventsEnabled) {
56	            throw new ConfigurationException("""
57	                    Found observer method for event type '%s', but the gRPC extension does not support security
58	                    events. Either disable security events with the 'quarkus.security.events.enabled'
59	                    configuration property, or remove security event CDI observers.""".formatted(observedSecurityEvent),
60	                    Set.of("quarkus.security.events.enabled"));
61	        }
62	    }
63	}
